refentry.refsect1:
&reftitle.description;
voidparse_str stringstring arrayresult
string लाई URL मार्फत pass गरिएको query string सरह parse गर्दछ र प्रदान गरिएको result array मा keys set गर्दछ। यदि कुनै result pass नगरिएमा, त्यसको सट्टा current scope भित्र variables का रूपमा values set गरिन्छ।

&reftitle.changelog;







     &Version;
     &Description;





    8.0.0
    result अब optional रहेन।



     7.2.0
     दोस्रो parameter बिना parse_str प्रयोग गर्दा अब एउटा E_DEPRECATED notice emit हुन्छ।

  &reftitle.examples;



    parse_str को प्रयोग


<?php
$str = "first=value&arr[]=foo+bar&arr[]=baz";

// Recommended
parse_str($str, $output);
echo $output['first'], PHP_EOL;  // value
echo $output['arr'][0], PHP_EOL; // foo bar
echo $output['arr'][1], PHP_EOL; // baz
?>





array keys वा local variables सिर्जना गर्दा parameter names मा रहेका कुनै पनि spaces र dots लाई underscores मा परिवर्तन गरिन्छ। यसो हुनुको कारण PHP मा variable names मा spaces वा dots राख्न अनुमति नहुनु हो, तर सिफारिस गरिएको result parameter सँग यो function प्रयोग गर्दा पनि यो लागू हुन्छ।
    parse_str मा name mangling


<?php
parse_str("My Value=Something", $output);
echo $output['My_Value']; // Something
?>
